<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
const route=useRoute()
import {api} from '@/api/client'
import PaperPicker from '@/components/PaperPicker.vue'
import {documentsApi,type DocumentVersion} from '@/api/documents'
import {renderMarkdown} from '@/shared/markdown'
interface Evidence{paper_id:number;document_version_id:string;file_version:string;page:number;quote:string;verification?:string}
interface Asset{hash:string;filename:string;paper_id:number}
interface Artifact{id:string;title:string;kind:string;revision:number;current_revision:number;markdown:string;status:string;paper_ids:number[];evidence:Evidence[];source_run_id:string|null;producer:{name:string};revisions:number[];files:Asset[]}
interface Knowledge{id:string;title:string;revision:number;current_revision:number;markdown:string;state:string;needs_review:boolean;claim_type:string;sources:{artifact_id:string;revision:number;title:string;evidence:Evidence[]}[];revisions:number[]}
const tab=ref<'artifacts'|'knowledge'|'recall'>('artifacts'),q=ref(''),status=ref(''),paper=ref(''),artifacts=ref<Artifact[]>([]),knowledge=ref<Knowledge[]>([]),selected=ref<Artifact|Knowledge|null>(null),error=ref(''),notice=ref(''),busy=ref(false),before=ref<number|null>(null),more=ref(false)
const form=ref(false),editing=ref(false),title=ref(''),markdown=ref(''),paperIds=ref(''),evidence=ref('[]'),kind=ref('note'),artifactStatus=ref('draft'),sourceRun=ref<string|null>(null),sources=ref('[]'),claimType=ref('inference')
const pickedPapers=computed({get:()=>paperIds.value?paperIds.value.split(',').map(Number):[],set:(v:number[])=>{paperIds.value=v.join(',')}})
const evidenceRows=ref<Evidence[]>([]),versionOptions=ref<Record<number,DocumentVersion[]>>({}),sourceRefs=ref<{artifact_id:string;revision:number}[]>([]),sourceOptions=ref<Artifact[]>([]),sourcePick=ref('')
async function addEvidence(){const pid=pickedPapers.value[0];if(!pid){error.value='请先选择关联论文';return}const data=await documentsApi.list(pid);versionOptions.value[pid]=data.documents.flatMap(d=>d.versions);const v=versionOptions.value[pid].find(v=>v.id===data.default_version_id)||versionOptions.value[pid][0];if(v)evidenceRows.value.push({paper_id:pid,document_version_id:v.id,file_version:v.file_hash,page:1,quote:''})}
async function evidencePaper(e:Evidence){const data=await documentsApi.list(e.paper_id);versionOptions.value[e.paper_id]=data.documents.flatMap(d=>d.versions);const v=versionOptions.value[e.paper_id][0];if(v){e.document_version_id=v.id;e.file_version=v.file_hash}}
function evidenceVersion(e:Evidence){const v=versionOptions.value[e.paper_id]?.find(v=>v.id===e.document_version_id);if(v)e.file_version=v.file_hash}
function addSource(){const a=sourceOptions.value.find(a=>a.id===sourcePick.value);if(a&&!sourceRefs.value.some(s=>s.artifact_id===a.id))sourceRefs.value.push({artifact_id:a.id,revision:a.current_revision})}
const attachedFiles=ref<Asset[]>([])
async function uploadAsset(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0],pid=pickedPapers.value[0];if(!file||!pid){error.value='请先选择关联论文';return}busy.value=true;try{const form=new FormData();form.append('paper_id',String(pid));form.append('file',file);const asset=await api<Asset>('/api/research/files',{form});if(!attachedFiles.value.some(f=>f.hash===asset.hash))attachedFiles.value.push(asset)}catch(e){error.value=String(e)}finally{busy.value=false;input.value=''}}
const isArtifact=computed(()=>selected.value!==null&&'kind' in selected.value)
async function load(append=false){busy.value=true;try{const params=new URLSearchParams({q:q.value,limit:'30'});if(append&&before.value)params.set('before',String(before.value));if(tab.value==='artifacts'&&paper.value)params.set('paper_id',paper.value);if(tab.value==='knowledge'&&status.value)params.set('state',status.value);const path=tab.value==='artifacts'?'artifacts':tab.value==='recall'?'knowledge/recall':'knowledge';const r=await api<{artifacts?:Artifact[];knowledge?:Knowledge[];has_more:boolean;next_before:number|null}>(`/api/research/${path}?${params}`);if(tab.value==='artifacts')artifacts.value=append?[...artifacts.value,...r.artifacts||[]]:r.artifacts||[];else knowledge.value=append?[...knowledge.value,...r.knowledge||[]]:r.knowledge||[];before.value=r.next_before;more.value=r.has_more;error.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
function switchTab(t:typeof tab.value){tab.value=t;selected.value=null;form.value=false;before.value=null;void load()}
async function open(id:string,revision?:number){try{selected.value=await api(`/api/research/${tab.value==='artifacts'?'artifacts':'knowledge'}/${id}${revision?'?revision='+revision:''}`);form.value=false}catch(e){error.value=String(e)}}
function draft(edit=false){editing.value=edit;const item=edit?selected.value:null;attachedFiles.value=item&&'kind' in item?[...(item.files||[])]:[];title.value=item?.title||'';markdown.value=item?.markdown||'';if(item&&'kind' in item){paperIds.value=item.paper_ids.join(',');evidenceRows.value=item.evidence.map(({verification,...rest})=>rest);for(const e of evidenceRows.value)void documentsApi.list(e.paper_id).then(d=>{versionOptions.value[e.paper_id]=d.documents.flatMap(x=>x.versions)});kind.value=item.kind;artifactStatus.value=item.status;sourceRun.value=item.source_run_id}else{paperIds.value='';evidenceRows.value=[];sourceRun.value=null;sourceRefs.value=item&&'sources' in item?item.sources.map(s=>({artifact_id:s.artifact_id,revision:s.revision})):[];void api<{artifacts:Artifact[]}>('/api/research/artifacts?limit=100').then(r=>{sourceOptions.value=r.artifacts}).catch(e=>{error.value=String(e)});claimType.value=item&&'claim_type' in item?item.claim_type:'inference'}form.value=true}
async function save(){busy.value=true;try{const item=editing.value?selected.value:null;const body=tab.value==='artifacts'?{title:title.value,markdown:markdown.value,kind:kind.value,status:artifactStatus.value,paper_ids:paperIds.value?paperIds.value.split(',').map(x=>Number(x.trim())):[],file_ids:attachedFiles.value.map(f=>f.hash),evidence:evidenceRows.value,source_run_id:sourceRun.value,producer:'web'}:{title:title.value,markdown:markdown.value,sources:sourceRefs.value,claim_type:claimType.value};selected.value=await api(`/api/research/${tab.value==='artifacts'?'artifacts':'knowledge'}${item?'/'+item.id:''}`,{method:item?'PATCH':'POST',body:{...body,...(item?{expected_revision:item.current_revision}:{})}});form.value=false;notice.value='已保存修订';await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function candidate(a:Artifact){switchTab('knowledge');draft();title.value=a.title;markdown.value=a.markdown;sourceRefs.value=[{artifact_id:a.id,revision:a.revision}]}
async function transition(action:string){const item=selected.value as Knowledge;if(!item)return;busy.value=true;try{selected.value=await api(`/api/research/knowledge/${item.id}/transition`,{body:{action,expected_revision:item.current_revision,expected_state:item.state}});notice.value=action==='publish'?'已发布，可用于召回':'状态已更新';await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function importExisting(){busy.value=true;try{const r=await api<{created:string[];skipped:unknown[]}>('/api/research/import-existing',{body:{limit:30}});notice.value=`已收录 ${r.created.length} 项，跳过 ${r.skipped.length} 项；未发布知识`;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
function openRoute(){const p=new URLSearchParams(location.hash.split('?')[1]||'');paper.value=p.get('paper_id')||'';void load();const id=route?.params.artifactId||p.get('artifact');if(id){tab.value='artifacts';void open(String(id),Number(route?.query.revision)||undefined)}}
onMounted(openRoute)
watch(()=>route?.fullPath,openRoute)
</script>
<template><main class="research"><RouterLink to="/?home=1">Firework · 首页</RouterLink><h1>研究产物与知识库</h1><button :disabled="busy" @click="importExisting">收录已有研究结果</button><nav><button @click="switchTab('artifacts')">研究产物</button><button @click="switchTab('knowledge')">知识审核</button><button @click="switchTab('recall')">已发布知识召回</button></nav><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form class="filters" @submit.prevent="load()"><input v-model="q" placeholder="搜索标题或知识内容" aria-label="搜索研究资料"/><input v-if="tab==='artifacts'" v-model="paper" placeholder="论文 ID（可选）"/><select v-if="tab==='knowledge'" v-model="status"><option value="">全部状态</option><option v-for="s in ['candidate','published','rejected','revoked']" :key="s">{{s}}</option></select><button :disabled="busy">搜索</button><button v-if="tab!=='recall'" type="button" @click="draft()">{{tab==='artifacts'?'新增产物':'新增知识候选'}}</button></form><p v-if="tab==='recall'">仅召回已发布、来源有效且未撤销的知识。当前为文本检索，不调用模型。</p><div class="research-grid"><aside><template v-if="tab==='artifacts'"><button v-for="a in artifacts" :key="a.id" class="record" @click="open(a.id)"><strong>{{a.title}}</strong><small>{{a.kind}} · v{{a.current_revision}} · {{a.status}}</small></button></template><template v-else><button v-for="k in knowledge" :key="k.id" class="record" @click="open(k.id)"><strong>{{k.title}}</strong><small>{{k.state}} · v{{k.current_revision}}{{k.needs_review?' · 来源变化，需复核':''}}</small></button></template><button v-if="more&&tab!=='recall'" :disabled="busy" @click="load(true)">加载更多</button></aside><section><form v-if="form" @submit.prevent="save"><h2>{{editing?'保存新修订':'新增'}}</h2><label>名称<input v-model="title" required maxlength="200"/></label><template v-if="tab==='artifacts'"><fieldset :disabled="editing"><legend>关联论文</legend><PaperPicker v-model="pickedPapers"/></fieldset><label>产物类型<select v-model="kind"><option v-for="t in ['reading','review','comparison','guide','frontier','note','file']" :key="t">{{t}}</option></select></label><label>完成状态<select v-model="artifactStatus"><option v-for="s in ['draft','complete','partial','failed']" :key="s">{{s}}</option></select></label><fieldset><legend>附件</legend><input type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.md,.json" :disabled="busy||!pickedPapers.length" @change="uploadAsset"/><p v-for="(f,i) in attachedFiles" :key="f.hash">{{f.filename}} <button type="button" @click="attachedFiles.splice(i,1)">移除</button></p></fieldset><fieldset><legend>原文证据</legend><button type="button" @click="addEvidence">添加证据</button><div v-for="(e,i) in evidenceRows" :key="i"><select v-model.number="e.paper_id" @change="evidencePaper(e)"><option v-for="pid in pickedPapers" :key="pid" :value="pid">论文 {{pid}}</option></select><select v-model="e.document_version_id" @change="evidenceVersion(e)"><option v-for="v in versionOptions[e.paper_id]||[]" :key="v.id" :value="v.id">{{v.label}}</option></select><input v-model.number="e.page" type="number" min="1" max="300" aria-label="证据页码"/><textarea v-model="e.quote" rows="2" placeholder="原文引句；留空表示仅引用页面"/><button type="button" @click="evidenceRows.splice(i,1)">移除证据</button></div></fieldset></template><template v-else><label>知识类型<select v-model="claimType"><option value="source">原文事实</option><option value="inference">AI / 研究推断</option><option value="personal">个人观点</option></select></label><fieldset><legend>来源产物</legend><select v-model="sourcePick"><option value="">选择已有产物</option><option v-for="a in sourceOptions" :key="a.id" :value="a.id">{{a.title}} · v{{a.current_revision}}</option></select><button type="button" @click="addSource">添加来源</button><p v-for="(s,i) in sourceRefs" :key="s.artifact_id">{{sourceOptions.find(a=>a.id===s.artifact_id)?.title||s.artifact_id}} · 修订 {{s.revision}} <button type="button" @click="sourceRefs.splice(i,1)">移除</button></p></fieldset></template><label>Markdown 内容<textarea v-model="markdown" rows="12" required/></label><button :disabled="busy">保存{{tab==='knowledge'?'为候选':''}}</button><button type="button" @click="form=false">取消</button></form><template v-else-if="selected"><h2>{{selected.title}}</h2><p>{{selected.id}} · v{{selected.revision}}</p><label>历史修订<select :value="selected.revision" @change="open(selected!.id,Number(($event.target as HTMLSelectElement).value))"><option v-for="r in selected.revisions" :key="r" :value="r">{{r}}</option></select></label><button v-if="tab!=='recall'" @click="draft(true)">编辑为新修订</button><template v-if="isArtifact"><a :href="`/api/research/artifacts/${selected.id}/markdown?revision=${selected.revision}`">下载 Markdown</a><button @click="candidate(selected as Artifact)">提取为知识候选</button><RouterLink v-if="(selected as Artifact).source_run_id" :to="`/runs/${(selected as Artifact).source_run_id}`">来源运行</RouterLink><h3 v-if="(selected as Artifact).files?.length">附件</h3><p v-for="f in (selected as Artifact).files" :key="f.hash"><a :href="`/api/research/files/${f.hash}`">{{f.filename}}</a></p><h3>原文证据</h3><p v-for="(e,i) in (selected as Artifact).evidence" :key="i"><a :href="`/api/library/papers/${e.paper_id}/document-versions/${e.document_version_id}/file?inline=true#page=${e.page}`" target="_blank" rel="noopener">论文{{e.paper_id}} · 原版本第{{e.page}}页</a> {{e.quote}}</p></template><template v-else><p>{{(selected as Knowledge).claim_type}} · {{(selected as Knowledge).state}}</p><p v-if="(selected as Knowledge).needs_review">来源已变化，已暂停默认召回，请重新审核。</p><p v-if="selected.revision!==selected.current_revision">历史版本只读，请切换到最新修订后审核。</p><div class="actions" v-if="tab!=='recall' && selected.revision===selected.current_revision"><button v-if="(selected as Knowledge).state==='candidate'" :disabled="busy" @click="transition('publish')">审核并发布</button><button v-if="(selected as Knowledge).state==='candidate'" :disabled="busy" @click="transition('reject')">驳回</button><button v-if="(selected as Knowledge).state==='published'" :disabled="busy" @click="transition('revoke')">撤销发布</button><button v-if="['rejected','revoked'].includes((selected as Knowledge).state)" :disabled="busy" @click="transition('reopen')">重新审核</button></div><h3>来源</h3><p v-for="s in (selected as Knowledge).sources" :key="s.artifact_id"><a href="#" @click.prevent="tab='artifacts';open(s.artifact_id,s.revision)">{{s.title}} · v{{s.revision}}</a></p></template><div class="markdown-content" v-html="renderMarkdown(selected.markdown)"></div></template><p v-else>选择记录查看内容、版本与证据。</p></section></div></main></template>
<style scoped>.research{max-width:1300px;margin:auto;padding:24px}.research nav,.filters,.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.research-grid{display:grid;grid-template-columns:300px minmax(0,1fr);gap:24px}.record{display:grid;text-align:left;width:100%;padding:12px;margin:6px 0;gap:6px}.record small{color:var(--muted)}label{display:grid;gap:6px;margin:12px 0}input,select,textarea{padding:8px;max-width:100%;box-sizing:border-box}textarea{width:100%}.markdown-content{overflow-wrap:anywhere}a,button{margin-right:8px}[role=alert]{color:var(--danger)}@media(max-width:750px){.research-grid{grid-template-columns:1fr}}</style>
